WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_trv_m_once'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '单次相遇', 'kp-trv-m-once', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "单次相遇"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心公式：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "总路程 = (V甲 + V乙) × 相遇时间。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "两人从两地同时相向而行，直到碰面。这是所有复杂相遇问题（多次相遇、折返相遇）的原子模型。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "相遇的过程，本质上是甲走的路程和乙走的路程拼成了一整条线段。"}]}, {"type": "katexBlock", "attrs": {"content": "S_{总} = S_{甲} + S_{乙} = V_{甲}T + V_{乙}T = (V_{甲} + V_{乙})T"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[画出横线, 两端标上甲乙的起点] --> B[标出中间的相遇点]\nB --> C[提取 S总, V甲, V乙]\nC --> D[套入相遇公式求出 T相遇]\nD --> E[如果要求甲走的距离, 回头用 V甲 × T相遇 单独计算]"}}]}$$ AS jsonb), NULL, '单次相遇的核心考点与实战推导。', category_node.id, CAST('["数量关系", "行程问题", "单次相遇"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_trv_m_once", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
